// Normalized summary, present when the report is JSON with format and streams. Narrow on `kind` before reading `video`, `audio` or `image`.
//
// FfprobeSummary holds one variant, matching Kind. A kind newer than this SDK sets
// Kind and leaves every variant nil.
type FfprobeSummary struct {
	Kind  FfprobeSummaryKind
	Video *FfprobeVideoSummary
	Audio *FfprobeAudioSummary
	Image *FfprobeImageSummary
	Other *FfprobeOtherSummary
}

// UnmarshalJSON reads the variant kind names.
func (u *FfprobeSummary) UnmarshalJSON(b []byte) error {
	var d struct {
		V FfprobeSummaryKind `json:"kind"`
	}
	if err := json.Unmarshal(b, &d); err != nil {
		return err
	}
	*u = FfprobeSummary{Kind: d.V}
	switch d.V {
	case "video":
		u.Video = new(FfprobeVideoSummary)
		return json.Unmarshal(b, u.Video)
	case "audio":
		u.Audio = new(FfprobeAudioSummary)
		return json.Unmarshal(b, u.Audio)
	case "image":
		u.Image = new(FfprobeImageSummary)
		return json.Unmarshal(b, u.Image)
	case "other":
		u.Other = new(FfprobeOtherSummary)
		return json.Unmarshal(b, u.Other)
	}
	return nil
}

